"""
Contract: perceive(observation_history) -> str must never raise.
Outputs a concise (<2000 char) text summary of non-background cells,
including their (row, col, colour). The background colour is determined
as the most frequent colour in the grid.
"""

import json
from collections import Counter


def _parse_grid(obs: str):
    """Extract the 2D colour grid as list[list[str]] (rows of colour-name strings).

    Anchor on the generic '[[' / ']]' so it works regardless of the header text that precedes
    the grid. Do NOT gate on the observation *starting* with '[[': Autumn observations are
    prefixed by a "Task:/Step:/..." header, so the grid begins mid-string. Returns None on
    failure (caller degrades gracefully, never raises)."""
    if not obs:
        return None
    start = obs.find("[[")
    end = obs.rfind("]]")
    if start == -1 or end == -1 or end < start:
        return None
    try:
        grid = json.loads(obs[start : end + 2])
    except Exception:
        return None
    if not grid or not isinstance(grid, list) or not isinstance(grid[0], list):
        return None
    return grid


def _get_background_colour(grid):
    """Return the most frequent colour in the grid (assumed background)."""
    flat = [cell for row in grid for cell in row]
    if not flat:
        return None
    # Count frequencies; return the most common one
    most_common = Counter(flat).most_common(1)
    if most_common:
        return most_common[0][0]
    return None


def perceive(observation_history: list[str]) -> str:
    # always return a non-empty string – even on error
    try:
        obs = observation_history[-1] if observation_history else ""
        grid = _parse_grid(obs)
        if grid is None:
            return "error_no_grid"

        background = _get_background_colour(grid)
        if background is None:
            return "error_no_background"

        # Collect all non-background cells
        features = []
        for r, row in enumerate(grid):
            for c, colour in enumerate(row):
                if colour != background:
                    features.append(f"{r},{c},{colour}")

        if not features:
            # No non-background cells
            return "empty_grid"

        # Build summary string, sorted for consistency
        features.sort()
        result = "; ".join(features)

        # Enforce <2000 characters (truncate if needed, but unlikely)
        if len(result) > 1999:
            # Truncate last complete cell; keep as many as fit under 2000
            truncated = []
            length = 0
            for f in features:
                item = f"{f}; "  # will be joined later
                if length + len(item) < 2000:
                    truncated.append(f)
                    length += len(item)
                else:
                    break
            result = "; ".join(truncated)

        return result if result else "empty_grid"

    except Exception:
        # Never raise; return a fallback non-empty string
        return "perception_error"

import json
from collections import Counter
from typing import List, Optional, Tuple

def _parse_grid(obs: str) -> Optional[List[List[str]]]:
    """Extract the 2D colour grid from the observation string."""
    if not obs:
        return None
    start = obs.find("[[")
    end = obs.rfind("]]")
    if start == -1 or end == -1 or end < start:
        return None
    try:
        grid = json.loads(obs[start:end+2])
    except Exception:
        return None
    if not isinstance(grid, list) or not grid or not isinstance(grid[0], list):
        return None
    return grid

def _get_background(grid: List[List[str]]) -> Optional[str]:
    """Return the most frequent colour (assumed background)."""
    flat = [cell for row in grid for cell in row]
    if not flat:
        return None
    most = Counter(flat).most_common(1)
    return most[0][0] if most else None

def _extract_objects(grid: List[List[str]], bg: str) -> List[Tuple[int,int,str]]:
    """Return list of (row, col, colour) for non-background cells."""
    objs = []
    for r, row in enumerate(grid):
        for c, col in enumerate(row):
            if col != bg:
                objs.append((r, c, col))
    return objs

def _match_objects(prev: List[Tuple[int,int,str]],
                   curr: List[Tuple[int,int,str]],
                   max_dist: int = 2) -> dict:
    """Match current objects to previous objects by colour and nearest neighbour.
    Returns dict: idx_in_curr -> (dr, dc) or None if new."""
    # Build a mapping: for each colour, list of prev positions
    prev_by_colour = {}
    for i, (pr, pc, pc_ol) in enumerate(prev):
        prev_by_colour.setdefault(pc_ol, []).append((i, pr, pc))

    matched_curr = [False] * len(curr)
    match = {}   # curr_idx -> (dr, dc)

    # For each prev object, try to match to best current of same colour
    # (greedy: closest)
    for colour, plist in prev_by_colour.items():
        # get current objects of same colour not matched yet
        curr_candidates = [(j, (cr, cc)) for j, (cr, cc, col) in enumerate(curr)
                           if col == colour and not matched_curr[j]]
        for pi, pr, pc in plist:
            if not curr_candidates:
                break
            # find closest (Manhattan)
            best = min(curr_candidates,
                       key=lambda x: abs(x[1][0]-pr) + abs(x[1][1]-pc))
            if abs(best[1][0]-pr) + abs(best[1][1]-pc) <= max_dist:
                matched_curr[best[0]] = True
                dr = best[1][0] - pr
                dc = best[1][1] - pc
                match[best[0]] = (dr, dc)
            # remove that candidate
            curr_candidates.remove(best)   # might fail if best not in list? but it is
    # remaining curr objects are new -> no delta
    for j in range(len(curr)):
        if not matched_curr[j]:
            match[j] = None   # new object
    return match

def _relational_info(objs: List[Tuple[int,int,str]]) -> List[str]:
    """For each blue object, compute column difference to nearest red in same row.
    Returns list of strings like 'r,c,blue,nearestRedColDiff' or 'none'."""
    info = []
    reds = [(r,c) for r,c,col in objs if col == 'red']
    for r,c,col in objs:
        if col == 'blue' and reds:
            # find reds in same row
            same_row = [rc for rr, rc in reds if rr == r]
            if same_row:
                min_diff = min(abs(rc - c) for rc in same_row)
                info.append(f"{r},{c},{col},rDiff{min_diff}")
            else:
                info.append(f"{r},{c},{col},noRedRow")
        else:
            info.append(f"{r},{c},{col}")
    return info

def perceive(observation_history: List[str]) -> str:
    try:
        if not observation_history:
            return "empty_history"

        # Parse current grid
        obs = observation_history[-1]
        grid = _parse_grid(obs)
        if grid is None:
            return "grid_parse_error"

        bg = _get_background(grid)
        if bg is None:
            return "bg_detect_error"

        curr_objects = _extract_objects(grid, bg)

        # If previous observation exists, compute deltas
        deltas = {}
        if len(observation_history) >= 2:
            prev_obs = observation_history[-2]
            prev_grid = _parse_grid(prev_obs)
            if prev_grid is not None:
                prev_bg = _get_background(prev_grid)
                if prev_bg is not None:
                    prev_objects = _extract_objects(prev_grid, prev_bg)
                    deltas = _match_objects(prev_objects, curr_objects)

        # Combine object info with relational info
        lines = []
        for idx, (r,c,col) in enumerate(curr_objects):
            base = f"{r},{c},{col}"
            # add delta if available
            if idx in deltas and deltas[idx] is not None:
                dr, dc = deltas[idx]
                base += f",d{dr},{dc}"
            # add relational info
            if col == 'blue':
                # compute column distance to nearest red in same row
                reds_same_row = [rc for rc in curr_objects if rc[2]=='red' and rc[0]==r]
                if reds_same_row:
                    min_diff = min(abs(rc[1]-c) for rc in reds_same_row)
                    base += f",rDist{min_diff}"
                else:
                    base += ",noRedRow"
            lines.append(base)

        if not lines:
            return "empty_grid"

        result = "; ".join(lines)

        # Enforce length limit (2000 chars)
        if len(result) > 1999:
            # keep as many complete entries as fit under limit
            truncated = []
            length = 0
            for line in lines:
                item = line + "; "
                if length + len(item) < 2000:
                    truncated.append(line)
                    length += len(item)
                else:
                    break
            result = "; ".join(truncated)
            if not result:
                result = "truncated_info"

        return result

    except Exception:
        return "perception_error"

